   170  static const uint8_t *decode_priority(h2o_http2_priority_t *priority, const uint8_t *src)
   171  {
   172      uint32_t u4 = h2o_http2_decode32u(src);
   173      src += 4;
   174      priority->exclusive = u4 >> 31;
   175      priority->dependency = u4 & 0x7fffffff;

