   691  static int handle_data_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   692  {
   693      h2o_http2_data_payload_t payload;
   694      h2o_http2_stream_t *stream;
   695      int ret;
   696
   697      if ((ret = h2o_http2_decode_data_payload(&payload, frame, err_desc)) != 0)
   698          return ret;
   699
   700      /* update connection-level window */
   701      h2o_http2_window_consume_window(&conn->_input_window, frame->length);
   702      if (h2o_http2_window_get_avail(&conn->_input_window) <= H2O_HTTP2_SETTINGS_HOST_CONNECTION_WINDOW_SIZE / 2)
   703          send_window_update(conn, 0, &conn->_input_window,
   704                             H2O_HTTP2_SETTINGS_HOST_CONNECTION_WINDOW_SIZE - h2o_http2_window_get_avail(&conn->_input_window));
   705
   706      /* check state */
   707      if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) == NULL) {
   708          if (frame->stream_id <= conn->pull_stream_ids.max_open) {
   709              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   710              return 0;
   711          } else {
   712              *err_desc = "invalid DATA frame";
   713              return H2O_HTTP2_ERROR_PROTOCOL;
   714          }
   715      }
   716      if (stream->state != H2O_HTTP2_STREAM_STATE_RECV_BODY) {
   717          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   718          h2o_http2_stream_reset(conn, stream);
   719          return 0;
   720      }
   721
   722      /* update stream-level window (doing it here could end up in sending multiple WINDOW_UPDATE frames if the receive window is
   723       * fully-used, but no need to worry; in such case we'd be sending ACKs at a very fast rate anyways) */
   724      h2o_http2_window_consume_window(&stream->input_window.window, frame->length);
   725      if (frame->length != payload.length)
   726          update_stream_input_window(conn, stream, frame->length - payload.length);
   727
   728      /* actually handle the input */
   729      if (payload.length != 0 || (frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) != 0)
   730          handle_request_body_chunk(conn, stream, h2o_iovec_init(payload.data, payload.length),
   731                                    (frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) != 0);
